// Synthetic complete frames encoded and decoded by official Windows SDK.
// No SDK, credential, .local file or network is needed to run this test.
#include <aoq_media_control.h>
#include <cassert>
#include <cstdio>
#include <string>
#include <vector>
using namespace aoq_wire;using B=std::vector<uint8_t>;
static unsigned checks=0;
#define CHECK(x) do{++checks;assert(x);}while(0)
static B hex(const std::string& s){B b;auto d=[](char c){return c>='a'?c-'a'+10:c-'0';};for(size_t i=0;i<s.size();i+=2)b.push_back(uint8_t((d(s[i])<<4)|d(s[i+1])));return b;}
static B frame(const B& p){B b={16,uint8_t(p.size()>>8),uint8_t(p.size())};b.insert(b.end(),p.begin(),p.end());return b;}
static const char* sdk_fixtures[]={
    "100000",
    "10001201000f616f713a2f2f73796e746865746963",
    "10001202000f73796e74686574696320636c6f7365",
    "10002f01000f616f713a2f2f73796e74686574696302000f73796e74686574696320636c6f73650300080102030405060708",
    "",
};
int main(){std::string e;unsigned count=0;GoAway g;
 for(const char* fixture:sdk_fixtures){B b=hex(fixture);
  CHECK(decode_goaway(b.data(),b.size(),g,e)==ParseStatus::Ok&&g.consumed==b.size());
  const std::string uri=count==1||count==3?"aoq://synthetic":count==4?std::string(1024,'u'):"";
  const std::string reason=count==2||count==3?"synthetic close":count==4?std::string(256,'r'):"";
  CHECK(g.new_session_uri==uri&&g.reason_phrase==reason&&g.largest_request_id==(count==3?0x0102030405060708ULL:count==4?UINT64_MAX:0));
  for(size_t i=0;i<b.size();++i){g.reason_phrase="old";CHECK(decode_goaway(b.data(),i,g,e)==ParseStatus::NeedMore);CHECK(g.reason_phrase.empty()&&g.new_session_uri.empty()&&!g.consumed&&!g.largest_request_id);}
  auto both=b;both.insert(both.end(),b.begin(),b.end());CHECK(decode_goaway(both.data(),both.size(),g,e)==ParseStatus::Ok&&g.consumed==b.size());++count;
 }
 CHECK(count==5);CHECK(decode_goaway(nullptr,1,g,e)==ParseStatus::Invalid);CHECK(decode_goaway(nullptr,0,g,e)==ParseStatus::NeedMore);
 for(const char* p:{"01","010001","010000010000","03000700000000000000","030009000000000000000000","03000800000000000000000300080000000000000000"}){auto b=frame(hex(p));CHECK(decode_goaway(b.data(),b.size(),g,e)==ParseStatus::Invalid&&g.consumed==0);}
 for(unsigned which:{1u,2u}){size_t n=which==1?1025:257;B p={uint8_t(which),uint8_t(n>>8),uint8_t(n)};p.resize(p.size()+n,'x');auto b=frame(p);CHECK(decode_goaway(b.data(),b.size(),g,e)==ParseStatus::Invalid&&g.consumed==0);}
 auto b=frame({0xfe,0,2,1,2,2,0,2,'o','k'});CHECK(decode_goaway(b.data(),b.size(),g,e)==ParseStatus::Ok&&g.reason_phrase=="ok");
 b=frame({2,0,3,'a',0,'b'});CHECK(decode_goaway(b.data(),b.size(),g,e)==ParseStatus::Ok&&g.reason_phrase.size()==3); // Never C-string truncate untrusted reason.
 b={17,0,0};CHECK(decode_goaway(b.data(),b.size(),g,e)==ParseStatus::Invalid);
 b={16,0x41,1};CHECK(decode_goaway(b.data(),b.size(),g,e)==ParseStatus::Invalid);
 std::printf("{\"sdk_full_frame_fixtures\":%u,\"checks\":%u,\"pass\":true}\n",count,checks);
}
